/// Resolves a `catalog:` or `catalog:<name>` reference. The package name is
/// extracted from the override `key` (any version selector is stripped) and
/// looked up in the named catalog. An empty `catalog_name` resolves to the
/// `"default"` catalog.
fn resolve_catalog_override(
  key: &str,
  catalog_name: &str,
  catalogs: &Catalogs,
) -> Result<NpmOverrideValue, NpmOverridesError> {
  // extract the bare package name from the key, stripping any version
  // selector (e.g. "foo@^1.0.0" → "foo", "@scope/foo@^1" → "@scope/foo")
  let package_name = if let Some(rest) = key.strip_prefix('@') {
    match rest.find('@') {
      Some(idx) => &key[..idx + 1],
      None => key,
    }
  } else {
    match key.find('@') {
      Some(idx) => &key[..idx],
      None => key,
    }
  };

  let resolved_catalog = if catalog_name.is_empty() {
    "default"
  } else {
    catalog_name
  };

  let version = catalogs
    .get(resolved_catalog)
    .and_then(|catalog| catalog.get(package_name))
    .ok_or_else(|| NpmOverridesError::UnresolvedCatalog {
      key: key.to_string(),
      catalog: resolved_catalog.to_string(),
    })?;

  let version_req = VersionReq::parse_from_npm(version).map_err(|source| {
    NpmOverridesError::ValueParse {
      key: key.to_string(),
      value: version.to_string(),
      source,
